/** Inline SVG markup for an icon. Decorative (aria-hidden) unless a label is given. */
export function icon(name, size = 16, cls = "oct") {
  const p = PATHS[name]; if (!p) return "";
  const s = size > 16 && p[24] ? 24 : 16;
  return `<svg class="${cls}" width="${size}" height="${size}" viewBox="0 0 ${s} ${s}" fill="currentColor" aria-hidden="true" focusable="false">${p[s] || p[16]}</svg>`;
}
